/* Slot Arena — CROWN / a realtime championship film. */
#victory{position:fixed;inset:0;width:100vw;max-width:none;height:100vh;height:100dvh;max-height:none;margin:0;padding:0;border:0;border-radius:0;overflow:hidden;background:#030407;color:#fff;isolation:isolate;--winner-color:#73d9ef;--film-duration:26s}
#victory::backdrop{background:#000}#victory:not([open]){display:none!important}
#victory canvas{position:absolute;inset:0;width:100%;height:100%;pointer-events:none;z-index:3}
.cinema-haze{position:absolute;inset:0;background:radial-gradient(ellipse at 50% 35%,#b0782c29,transparent 55%),radial-gradient(ellipse at 50% 95%,#23415130,transparent 70%);opacity:0;transition:opacity 3s}
