.cinema-name span{background:linear-gradient(115deg,#9e7034 0%,#edc67e 18%,#fff8df 38%,#d6ac60 51%,#fff1c1 65%,#b8853d 82%,#f5d99b);background-size:250% 100%;background-clip:text;-webkit-background-clip:text;-webkit-text-fill-color:transparent;box-decoration-break:clone;-webkit-box-decoration-break:clone}.cinema-name.long-name{font-size:clamp(30px,5.4vw,82px)}
.cinema-player{display:flex;align-items:center;justify-content:center;gap:18px;font-size:clamp(18px,2.5vw,32px);font-weight:750;color:var(--winner-color);letter-spacing:.14em;text-transform:uppercase;opacity:0;transform:translateY(24px);transition:opacity 1s,transform 1.2s;max-width:90%;overflow-wrap:anywhere}.cinema-player:before,.cinema-player:after{content:'';width:55px;height:1px;background:currentColor;flex-shrink:0}
.cinema-recap{display:flex;justify-content:center;gap:42px;opacity:0;transform:translateY(18px);transition:opacity 1.3s,transform 1.3s;margin-top:22px}.cinema-recap strong{display:block;color:#f6e9ce;font-size:clamp(22px,3vw,40px);font-weight:400;font-variant-numeric:tabular-nums;line-height:1.2}.cinema-recap small{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:#bcab8b}.cinema-recap>div+div{border-left:1px solid #d0b57c33;padding-left:42px}.cinema-signature{color:#b7a17b;font-size:10px;text-transform:uppercase;letter-spacing:.35em;margin-top:24px;opacity:0;transition:opacity 2s}
