#victory[data-phase="reveal"] .cinema-name,#victory[data-phase="glory"] .cinema-name{opacity:1;transform:none;filter:none}#victory[data-phase="reveal"] .cinema-name span,#victory[data-phase="glory"] .cinema-name span{animation:cinema-gold 8s ease-out both}
