<script>
'use strict';
const ONLINE=true, BOOT=JSON.parse(document.getElementById('online-boot').textContent);
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='slot-arena-v1:'+location.pathname, clone=o=>JSON.parse(JSON.stringify(o));
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const fresh=()=>({schema:'slot-arena.v1',id:uid(),title:'Champions League des Slots',players:['Alex','Marc'],slots:[],order:'random',rounds:[],updatedAt:Date.now()});
let state=fresh(),history=[],diskHandle=null,diskQueue=Promise.resolve(),diskTimer,toastTimer,localOK=true;
const name=id=>state.slots.find(s=>s.id===id)?.name||'À déterminer';
const number=v=>{if(typeof v!=='string'||!v.trim())return null;const t=v.trim().replace(',','.');if(!/^\d+(\.\d+)?$/.test(t))return null;const n=Number(t);return Number.isFinite(n)&&n>=0&&n<=1e12?n:null};
function makeMatch(a=null,b=null){return{players:[a,b],scores:['',''],winner:null,bye:false}}
const owner=id=>state.slots.find(s=>s.id===id)?.owner??0;
const ownerBadge=id=>id?`<small class="owner-tag owner-${owner(id)}">${esc(state.players[owner(id)])}</small>`:'';
function bracketLayout(count){if(count===1)return[[1,0]];let a=Math.ceil(count/2),b=Math.floor(count/2);const layout=[[a,b]];while(a>1||b>1){a=Math.ceil(a/2);b=Math.ceil(b/2);layout.push([a,b])}layout.push([1,0]);return layout}
function matchSources(rounds,r,i,balanced){if(!balanced)return[i*2,i*2+1<rounds[r-1].length?i*2+1:null];if(r===rounds.length-1)return[0,1];const layout=bracketLayout(rounds[0].length),prev=layout[r-1],current=layout[r],right=i>=current[0],offset=right?prev[0]:0,index=offset+2*(right?i-current[0]:i),end=right?prev[0]+prev[1]:prev[0];return[index,index+1<end?index+1:null]}
function seedRounds(ids){const teams=[0,1].map(o=>ids.filter(id=>owner(id)===o));if(!teams[0].length||teams[0].length!==teams[1].length)throw Error('Il faut autant de slots pour chaque joueur.');state.bracket='balanced.v1';const rounds=bracketLayout(teams[0].length).map(([a,b])=>Array.from({length:a+b},()=>makeMatch()));rounds[0]=teams[0].map((id,i)=>makeMatch(id,teams[1][i]));sync(rounds,true);return rounds}
function sync(rounds=state.rounds,balanced=state.bracket==='balanced.v1'){for(let r=1;r<rounds.length;r++)for(let i=0;i<rounds[r].length;i++){const m=rounds[r][i],previous=rounds[r-1],[a,b]=matchSources(rounds,r,i,balanced),bye=b===null,p=[previous[a].winner,bye?null:previous[b].winner];if(m.players.some((v,k)=>v!==p[k])||m.bye!==bye){m.players=p;m.scores=['',''];m.winner=bye?p[0]:null;m.bye=bye}}}
function balanceState(s){if(s.bracket==='balanced.v1'||!s.rounds.length||s.rounds[0].some(m=>m.bye)||s.rounds.slice(1).flat().some(m=>(m.winner&&!m.bye)||m.scores.some(v=>v!=='')))return s;const first=s.rounds[0];s.rounds=bracketLayout(first.length).map(([a,b])=>Array.from({length:a+b},()=>makeMatch()));s.rounds[0]=first;s.bracket='balanced.v1';sync(s.rounds,true);return s}
function validState(s){if(!s||s.schema!=='slot-arena.v1'||typeof s.id!=='string'||typeof s.title!=='string'||s.title.length>80||!Number.isFinite(s.updatedAt)||!['random','list'].includes(s.order)||!Array.isArray(s.slots)||s.slots.length>128||!Array.isArray(s.rounds)||s.rounds.length>7)throw Error('Format de tournoi invalide.');
 const legacy=!s.players;if(legacy)s.players=['Alex','Marc'];if(!Array.isArray(s.players)||s.players.length!==2||s.players.some(n=>typeof n!=='string'||!n.trim()||n.length>40))throw Error('Joueurs invalides.');
 s.players=s.players.map((p,i)=>p.trim()==='Joueur '+(i+1)?['Alex','Marc'][i]:p);
 const ids=new Set();for(let i=0;i<s.slots.length;i++){const x=s.slots[i];if(legacy&&x)x.owner=i<Math.ceil(s.slots.length/2)?0:1;if(!x||typeof x.id!=='string'||ids.has(x.id)||typeof x.name!=='string'||!x.name.trim()||x.name.length>80||![0,1].includes(x.owner))throw Error('Liste de slots invalide.');ids.add(x.id)}
 if(s.bracket!==undefined&&s.bracket!=='balanced.v1')throw Error('Disposition invalide.');const balanced=s.bracket==='balanced.v1',layout=s.rounds.length&&balanced?bracketLayout(s.rounds[0].length):null;if(layout&&layout.length!==s.rounds.length)throw Error('Tours incohérents.');
 if(s.rounds.length){if(s.slots.length<2||s.rounds.at(-1).length!==1)throw Error('Tableau invalide.');const entered=[];
 for(let r=0;r<s.rounds.length;r++){const round=s.rounds[r];if(!Array.isArray(round)||!round.length||round.length>64||(balanced&&round.length!==layout[r][0]+layout[r][1])||(!balanced&&r&&round.length!==Math.ceil(s.rounds[r-1].length/2))||(r&&s.rounds[r-1].length===1))throw Error('Tour invalide.');
 for(let i=0;i<round.length;i++){const m=round[i];if(!m||!Array.isArray(m.players)||m.players.length!==2||!Array.isArray(m.scores)||m.scores.length!==2||typeof m.bye!=='boolean'||m.players.some(p=>p!==null&&!ids.has(p))||m.scores.some(v=>typeof v!=='string'||v.length>25))throw Error('Duel invalide.');
 let expectedBye=false;if(r===0){entered.push(...m.players.filter(Boolean));expectedBye=m.players[1]===null;if(!m.players[0])throw Error('Slot manquante.')}else{const[a,b]=matchSources(s.rounds,r,i,balanced);expectedBye=b===null;const p=[s.rounds[r-1][a].winner,expectedBye?null:s.rounds[r-1][b].winner];if(m.players.some((v,k)=>v!==p[k]))throw Error('Qualifications incohérentes.');}
